/**
 * Task Lists view — Vue 3 component.
 *
 * Reads /www/task-lists.json (generated by /shared/www/scripts/build-task-lists-json.py)
 * and renders a card grid: task list > sections > checkbox-item count.
 *
 * Vue is loaded from CDN in the blade view. This file exposes (as globals,
 * matching app.js style):
 *   - TASK_LISTS_JSON  : URL of the JSON feed
 *   - taskListsTabHTML(): markup placed inside renderApp()'s template — Vue
 *                         mounts into the inner #task-lists-app element
 *   - loadTaskLists() : (re)fetches the JSON and rerenders the grid
 *
 * Mounting is deferred until taskListsTabHTML()'s element is in the DOM,
 * which happens after renderApp(). loadTaskLists() handles first-mount.
 */

const TASK_LISTS_JSON = '/www/task-lists.json';

let _taskListsVm = null;

function taskListsTabHTML() {
    return `
        <div id="task-lists-tab" class="tab-page" style="display:none;">
            <div id="task-lists-app"></div>
        </div>
    `;
}

function _ensureTaskListsMounted() {
    if (_taskListsVm) return _taskListsVm;
    const el = document.getElementById('task-lists-app');
    if (!el || !window.Vue) return null;

    const { createApp, ref, computed } = window.Vue;

    const app = createApp({
        setup() {
            const generatedAt = ref('');
            const loading = ref(false);
            const error = ref('');
            const taskLists = ref([]);
            const jsonUrl = TASK_LISTS_JSON;

            async function load() {
                loading.value = true;
                error.value = '';
                try {
                    const resp = await fetch(TASK_LISTS_JSON + '?t=' + Date.now());
                    const data = await resp.json();
                    generatedAt.value = data.generated_at || '';
                    taskLists.value = data.task_lists || [];
                } catch (e) {
                    error.value = e.message;
                    taskLists.value = [];
                } finally {
                    loading.value = false;
                }
            }

            return { generatedAt, loading, error, taskLists, jsonUrl, load };
        },
        template: `
            <div class="header">
                <h1>Task Lists</h1>
                <button class="refresh-btn" @click="load">&#x21bb; Refresh</button>
                <a :href="jsonUrl" target="_blank" class="json-link">JSON</a>
                <span class="last-updated">{{ generatedAt ? 'Generated: ' + generatedAt : '' }}</span>
            </div>
            <div v-if="error" class="empty" style="color:#f85149;">
                Failed to load task-lists.json: {{ error }}
            </div>
            <div v-else-if="loading && !taskLists.length" class="empty">Loading...</div>
            <div v-else-if="!taskLists.length" class="empty">No task lists.</div>
            <div v-else style="display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:14px;padding:8px;">
                <task-list-card v-for="tl in taskLists" :key="tl.file" :tl="tl" />
            </div>
        `,
    });

    app.component('task-list-card', {
        props: ['tl'],
        computed: {
            sections() { return this.tl.sections || []; },
            total() { return this.sections.reduce((s, x) => s + (x.count || 0), 0); },
        },
        template: `
            <div style="background:linear-gradient(180deg,#1c2128,#161b22);border:1px solid #30363d;border-radius:10px;padding:12px;">
                <div style="font-size:13px;font-weight:600;color:#58a6ff;margin-bottom:8px;padding-bottom:6px;border-bottom:1px solid #30363d;word-break:break-word;">{{ tl.file }}</div>
                <task-list-section-row v-for="s in sections" :key="s.name" :section="s" />
                <div style="font-size:11px;color:#6e7681;margin-top:6px;">{{ sections.length }} sections &middot; {{ total }} items</div>
            </div>
        `,
    });

    app.component('task-list-section-row', {
        props: ['section'],
        computed: {
            count() { return this.section.count || 0; },
            has() { return this.count > 0; },
            badgeStyle() {
                return {
                    background: this.has ? '#1f6feb' : '#30363d',
                    color: this.has ? '#fff' : '#8b949e',
                    padding: '1px 7px',
                    borderRadius: '10px',
                    fontSize: '11px',
                    minWidth: '22px',
                    textAlign: 'center',
                };
            },
        },
        template: `
            <div style="display:flex;justify-content:space-between;align-items:center;background:#21262d;border:1px solid #30363d;border-radius:6px;padding:5px 9px;font-size:12px;margin-bottom:4px;">
                <span style="color:#c9d1d9;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1;">{{ section.name }}</span>
                <span :style="badgeStyle">{{ count }}</span>
            </div>
        `,
    });

    _taskListsVm = app.mount(el);
    return _taskListsVm;
}

function loadTaskLists() {
    const vm = _ensureTaskListsMounted();
    if (vm) vm.load();
}
